&lt;li style=&quot;font-weight: 400; font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-weight: 400; font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Paid time off for vacation - in your first year, you’ll start with 15 days (prorated in a to your start date)&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400; font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-weight: 400; font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Additional paid time off for organizational closures&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400; font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-weight: 400; font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;403(b) with a match of up to 3%&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400; font-family: helvetica, arial, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-weight: 400; font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Unlimited sick and personal time - if you need it, use it&lt;/span&gt;&lt;/li&gt;
